1	import fs from 'fs';
2	import os from 'os';
3	import path from 'path';
4	import { describe, expect, it, afterEach } from 'vitest';
5	
6	import { chunkText, findDocuments, indexDocuments, simpleEmbed } from './index.js';
7	
8	const tmpDirs = [];
9	afterEach(() => {
10	  while (tmpDirs.length) {
11	    const dir = tmpDirs.pop();
12	    fs.rmSync(dir, { recursive: true, force: true });
13	  }
14	});
15	
16	const createFixtureDir = () => {
17	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-rag-'));
18	  tmpDirs.push(dir);
19	  return dir;
20	};
21	
22	describe('RAG indexing', () => {
23	  it('finds markdown documents recursively', () => {
24	    const dir = createFixtureDir();
25	    const sub = path.join(dir, 'docs');
26	    fs.mkdirSync(sub);
27	    fs.writeFileSync(path.join(dir, 'root.md'), '# Root');
28	    fs.writeFileSync(path.join(sub, 'nested.md'), '# Nested');
29	    fs.writeFileSync(path.join(sub, 'ignore.txt'), 'text'); // should be included
30	    fs.writeFileSync(path.join(sub, 'skip.bin'), 'binary');
31	
32	    const results = findDocuments(dir);
33	    expect(results.length).toBe(3);
34	    expect(results.every((filePath) => filePath.endsWith('.md') || filePath.endsWith('.txt'))).toBe(true);
35	  });
36	
37	  it('chunks text using word boundaries', () => {
38	    const text = 'one two three four five six seven eight nine ten';
39	    const chunks = chunkText(text, { chunkSize: 3 });
40	    expect(chunks).toEqual([
41	      'one two three',
42	      'four five six',
43	      'seven eight nine',
44	      'ten'
45	    ]);
46	  });
47	
48	  it('creates embeddings with consistent length', () => {
49	    const embedding = simpleEmbed('hello world');
50	    expect(embedding).toHaveLength(8);
51	    const norm = Math.sqrt(embedding.reduce((sum, value) => sum + value * value, 0));
52	    expect(Number(norm.toFixed(6))).toBeCloseTo(1, 5);
53	  });
54	
55	  it('indexes documents into vector store file', () => {
56	    const dir = createFixtureDir();
57	    const docPath = path.join(dir, 'policy.md');
58	    fs.writeFileSync(docPath, 'This is a policy document that requires responsible usage.', 'utf8');
59	
60	    const output = path.join(dir, 'index', 'frai-index.json');
61	    const index = indexDocuments({
62	      input: dir,
63	      output,
64	      chunkSize: 5
65	    });
66	
67	    expect(index.metadata.documentCount).toBe(1);
68	    expect(index.entries.length).toBeGreaterThan(0);
69	    expect(fs.existsSync(output)).toBe(true);
70	
71	    const saved = JSON.parse(fs.readFileSync(output, 'utf8'));
72	    expect(saved.metadata.entryCount).toBe(index.entries.length);
73	  });
74	});
