1	import { CORE_PURPOSE } from './constants.js';
2	import {
3	  biasQuestions,
4	  coreQuestions,
5	  dataProtectionQuestions,
6	  dataSourceQuestions,
7	  defaultImpactQuestions,
8	  impactQuestionSet,
9	  monitoringQuestions,
10	  performanceQuestions
11	} from './questions.js';
12	
13	const hasSensitiveData = (dataType) =>
14	  dataType === 'sensitive' || dataType.includes('personal');
15	
16	const getImpactQuestions = (purpose) =>
17	  impactQuestionSet[purpose] ?? defaultImpactQuestions;
18	
19	export const QUESTION_SEQUENCES = {
20	  core: coreQuestions,
21	  performance: performanceQuestions,
22	  monitoring: monitoringQuestions,
23	  bias: biasQuestions
24	};
25	
26	export async function runQuestionnaire({ prompt }) {
27	  if (typeof prompt !== 'function') {
28	    throw new TypeError('runQuestionnaire requires a prompt function');
29	  }
30	
31	  const core = await prompt(coreQuestions);
32	  const impact = await prompt(getImpactQuestions(core.purpose));
33	
34	  const data = await prompt(
35	    hasSensitiveData(core.dataType) ? dataProtectionQuestions : dataSourceQuestions
36	  );
37	
38	  const performance = await prompt(performanceQuestions);
39	  const monitoring = await prompt(monitoringQuestions);
40	  const bias = await prompt(biasQuestions);
41	
42	  return { core, impact, data, performance, monitoring, bias };
43	}
44	
45	export { CORE_PURPOSE };
