34	export function findDocuments(inputPaths, { extensions = DEFAULT_INPUT_EXTENSIONS, fs: fsModule = defaultFs } = {}) {
35	  const sources = normalizeArray(inputPaths ?? process.cwd());
36	  const files = [];
37	
38	  for (const source of sources) {
39	    const absolute = path.resolve(source);
40	    const stats = safeStat(fsModule, absolute);
41	    if (stats.isDirectory()) {
42	      const entries = safeReadDir(fsModule, absolute);
43	      for (const entry of entries) {
44	        const entryPath = path.join(absolute, entry);
45	        const entryStats = safeStat(fsModule, entryPath);
46	        if (entryStats.isDirectory()) {
47	          files.push(...findDocuments(entryPath, { extensions, fs: fsModule }));
48	        } else if (extensions.includes(path.extname(entry).toLowerCase())) {
49	          files.push(entryPath);
50	        }
51	      }
52	    } else if (stats.isFile()) {
53	      if (extensions.includes(path.extname(absolute).toLowerCase())) {
54	        files.push(absolute);
55	      }
56	    }
57	  }
58	
59	  return Array.from(new Set(files)).sort();
60	}
