62	export function generateReport({
63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString()
67	}) {
68	  const totalSamples = evaluations.reduce((total, metric) => {
69	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
70	    return total;
71	  }, 0);
72	
73	  return {
74	    metadata: {
75	      generatedAt,
76	      outputsPath,
77	      referencesPath,
78	      totalSamples
79	    },
80	    metrics: evaluations
81	  };
82	}
