275	export function calculateReadiness(plan) {
276	  const checkpoints = {
277	    dataset: false,
278	    evaluation: false,
279	    approvals: false,
280	    monitoring: false,
281	    audit: false
282	  };
283	
284	  if (isPlainObject(plan.dataset)) {
285	    const { useCases = [], sources = [], qualityChecks = {} } = plan.dataset;
286	    checkpoints.dataset =
287	      useCases.length > 0 &&
288	      sources.length > 0 &&
289	      hasStringValue(qualityChecks.biasAssessment) &&
290	      hasStringValue(qualityChecks.manualReview);
291	  }
292	
293	  if (isPlainObject(plan.evaluation)) {
294	    const { metrics = [], gateCriteria = {} } = plan.evaluation;
295	    checkpoints.evaluation =
296	      metrics.length > 0 &&
297	      metrics.every((metric) => typeof metric.threshold === 'number') &&
298	      typeof gateCriteria.minimumSuccessRate === 'number';
299	  }
300	
301	  if (isPlainObject(plan.approvals) && Array.isArray(plan.approvals.stakeholders)) {
302	    const stakeholders = plan.approvals.stakeholders;
303	    checkpoints.approvals =
304	      stakeholders.length > 0 && stakeholders.every((stakeholder) => stakeholder.status === 'approved');
305	  }
306	
307	  if (isPlainObject(plan.monitoring)) {
308	    const { owner, metrics = [], rollbackPlan = {} } = plan.monitoring;
309	    checkpoints.monitoring =
310	      hasStringValue(owner) &&
311	      metrics.length > 0 &&
312	      hasStringValue(rollbackPlan.trigger) &&
313	      Array.isArray(rollbackPlan.steps) &&
314	      rollbackPlan.steps.length > 0;
315	  }
316	
317	  if (isPlainObject(plan.audit)) {
318	    const { artefacts = [] } = plan.audit;
319	    checkpoints.audit = artefacts.length > 0;
320	  }
321	
322	  const blockers = Object.entries(checkpoints)
323	    .filter(([, complete]) => !complete)
324	    .map(([name]) => name);
325	
326	  let status = 'ready';
327	  if (blockers.length > 0) {
328	    const criticalBlockers = blockers.filter((item) => item === 'evaluation' || item === 'approvals');
329	    status = criticalBlockers.length > 0 ? 'blocked' : 'pending';
330	  }
331	
332	  const completed = Object.values(checkpoints).filter(Boolean).length;
333	  const score = completed / Object.keys(checkpoints).length;
334	
335	  return {
336	    status,
337	    score,
338	    checkpoints
339	  };
340	}
